-- 테이블 ipforce.COLLECTION_INFO_TB 구조 내보내기
CREATE TABLE IF NOT EXISTS `COLLECTION_INFO_TB` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) DEFAULT NULL COMMENT '유저 고유번호',
  `project_id` int(11) DEFAULT NULL,
  `source_type` enum('DB','FILE','search','upload') NOT NULL COMMENT '컬렉션 데이터 경로',
  `project_code` tinytext NOT NULL COMMENT '프로젝트 고유번호',
  `project_name` varchar(50) NOT NULL DEFAULT '',
  `collection_code` tinytext NOT NULL COMMENT '컬렉션 고유번호',
  `collection_name` tinytext NOT NULL COMMENT '컬렉션 이름',
  `collection_category` varchar(10) NOT NULL DEFAULT '0' COMMENT '컬렉션 분류번호',
  `collection_data_num` int(11) NOT NULL DEFAULT 0,
  `collection_data_ratio` float NOT NULL DEFAULT 0,
  `mean_vector` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '컬렉션 모음의 평균 벡터',
  `created_datetime` datetime NOT NULL COMMENT '최초 생성 날짜',
  `updated_datetime` datetime NOT NULL COMMENT '마지막 수정 날짜',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2494 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

